const users=[{name:'Marina Costa',email:'marina.costa@torresul.com',role:'COORDENADOR',status:'ATIVO',last:'Agora'},{name:'Guilherme Arruda',email:'guilherme.arruda@torresul.com',role:'ADMINISTRADOR',status:'ATIVO',last:'Hoje, 08:42'},{name:'Rafael Nunes',email:'rafael.nunes@torresul.com',role:'OPERADOR',status:'ATIVO',last:'Hoje, 07:15'}];
function renderHistory(){page.innerHTML=header('HISTORICO OPERACIONAL','Relatorio diario compilado da operacao')+`<div class="report-toolbar"><label>DATA DO RELATORIO<input type="date" value="2026-08-26"></label><button class="btn">← DIA ANTERIOR</button><button class="btn">PROXIMO DIA →</button><button class="btn btn-primary" onclick="toast('Relatorio diario exportado')">EXPORTAR RELATORIO</button></div><section class="report-banner"><div><span>RELATORIO DIARIO</span><strong>26 DE AGOSTO DE 2026</strong><small>Consolidado operacional · Turnos T1, T2 e T3</small></div><div class="report-status">● FECHAMENTO EM ANDAMENTO</div></section><div class="management-kpis report-kpis"><div class="management-kpi"><span>OPERACOES DO DIA</span><strong>48</strong><em>29 finalizadas</em></div><div class="management-kpi"><span>TONELADAS</span><strong>184 <small>t</small></strong><em>2.460 fardos</em></div><div class="management-kpi"><span>SLA</span><strong>91<small>%</small></strong><em>44 dentro · 4 fora</em></div><div class="management-kpi"><span>OCUPACAO MEDIA</span><strong>64<small>%</small></strong><em>7 de 11 docas</em></div></div><div class="management-grid"><section class="panel"><div class="panel-head"><span class="panel-title">RESUMO POR TURNO</span><span class="panel-meta">Relatorio compilado</span></div><table class="operations report-table"><thead><tr><th>TURNO</th><th>OPERACOES</th><th>TONELADAS</th><th>FARDOS</th><th>SLA</th><th>PERDAS</th></tr></thead><tbody><tr><td class="dt">T1</td><td>18</td><td>72 t</td><td>960</td><td class="risk green">94%</td><td>1</td></tr><tr><td class="dt">T2</td><td>21</td><td>81 t</td><td>1.080</td><td class="risk orange">90%</td><td>2</td></tr><tr><td class="dt">T3</td><td>9</td><td>31 t</td><td>420</td><td class="risk green">89%</td><td>1</td></tr></tbody></table></section><section class="panel"><div class="panel-head"><span class="panel-title">PRINCIPAIS OCORRENCIAS</span><span class="panel-meta">4 registros</span></div><div class="history-list"><div><b>Espera de doca</b><span>2 ocorrencias</span></div><div><b>Atraso de chegada</b><span>1 ocorrencia</span></div><div><b>Falta de equipamento</b><span>1 ocorrencia</span></div></div></section></div>`;}
function renderUsers(){page.innerHTML=header('USUARIOS','Criacao e administracao de logins da Torre Sul')+`<div class="users-toolbar"><div><strong>USUARIOS CADASTRADOS</strong><span>Controle de acessos e perfis</span></div><button class="btn btn-primary" onclick="document.querySelector('#new-user').classList.toggle('open')">＋ CRIAR LOGIN</button></div><section class="panel new-user" id="new-user"><div class="panel-head"><span class="panel-title">NOVO LOGIN</span><span class="panel-meta">Campos obrigatorios</span></div><div class="user-form"><input placeholder="Nome completo"><input type="email" placeholder="E-mail corporativo"><select><option>Selecione o perfil</option><option>ADMINISTRADOR</option><option>COORDENADOR</option><option>SUPERVISOR</option><option>OPERADOR</option><option>VISUALIZACAO</option></select><input type="password" placeholder="Senha temporaria"><button class="btn btn-primary" onclick="toast('Login criado com sucesso')">CRIAR USUARIO</button></div></section><section class="panel user-table"><div class="panel-head"><span class="panel-title">ACESSOS ATIVOS</span><span class="panel-meta">${users.length} usuarios</span></div><div class="table-wrap"><table class="operations"><thead><tr><th>NOME</th><th>E-MAIL</th><th>PERFIL</th><th>STATUS</th><th>ULTIMO ACESSO</th><th></th></tr></thead><tbody>${users.map(user=>`<tr><td><strong>${user.name}</strong></td><td class="muted">${user.email}</td><td>${user.role}</td><td><span class="status green"><i></i>${user.status}</span></td><td>${user.last}</td><td><button class="btn" onclick="toast('Edicao de ${user.name} aberta')">EDITAR</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function renderSettings(){page.innerHTML=header('CONFIGURACOES','Gerencie as regras e parametros de toda a aplicacao')+`<div class="settings-grid"><section class="panel settings-panel"><div class="panel-head"><span class="panel-title">TEMPOS OPERACIONAIS</span><span class="panel-meta">Aplicados a todos os calculos</span></div><div class="settings-form"><label>SLA OUTBOUND BATIDO<input value="02:00:00"></label><label>SLA OUTBOUND PALETIZADO<input value="01:30:00"></label><label>TEMPO MAXIMO DE PATIO<input value="00:30:00"></label><label>TEMPO MAXIMO DE DOCA<input value="02:00:00"></label><label>ATRASO DE CHEGADA<input value="00:15:00"></label></div></section><section class="panel settings-panel"><div class="panel-head"><span class="panel-title">RISCO E ALERTAS</span><span class="panel-meta">Faixas de monitoramento</span></div><div class="settings-form"><label>ATENCAO A PARTIR DE<input value="70 %"></label><label>CRITICO A PARTIR DE<input value="90 %"></label><label>PERDA A PARTIR DE<input value="100 %"></label><label>ATUALIZACAO AUTOMATICA<select><option>A cada 30 segundos</option><option>A cada 1 minuto</option></select></label></div></section><section class="panel settings-panel"><div class="panel-head"><span class="panel-title">TURNOS DA OPERACAO</span><span class="panel-meta">America/Sao_Paulo</span></div><div class="settings-form"><label>TURNO T1<input value="05:30 - 13:40"></label><label>TURNO T2<input value="13:40 - 22:00"></label><label>TURNO T3<input value="22:00 - 05:30"></label></div></section><section class="panel settings-panel"><div class="panel-head"><span class="panel-title">OPERACAO E DADOS</span><span class="panel-meta">Parametros gerais</span></div><div class="settings-form"><label>QUANTIDADE DE DOCAS<input value="11"></label><label>FUSO HORARIO<select><option>America/Sao_Paulo</option></select></label><label>FORMATO DE DATA<select><option>DD/MM/AAAA</option></select></label></div></section></div><div class="settings-actions"><span class="muted">Alteracoes ficam registradas na auditoria.</span><button class="btn" onclick="toast('Configuracoes restauradas')">RESTAURAR PADRAO</button><button class="btn btn-primary" onclick="toast('Configuracoes salvas com sucesso')">SALVAR CONFIGURACOES</button></div>`;}
function renderManagerial(){page.className='page managerial-page'; page.innerHTML=header('DASHBOARD GERENCIAL','Analise de volume e produtividade da operacao')+`<div class="manager-filters"><span>PERIODO</span><button class="btn active-filter">26 AGO 2026</button><button class="btn">ULTIMOS 7 DIAS</button><button class="btn">ESTE MES</button><span class="manager-updated">Atualizado agora</span></div><div class="management-kpis"><div class="management-kpi"><span>TONELADAS TOTAIS</span><strong>184 <small>t</small></strong><em>Volume movimentado</em></div><div class="management-kpi"><span>FARDOS TOTAIS</span><strong>2.460</strong><em>Unidades movimentadas</em></div><div class="management-kpi"><span>CLIENTES ATENDIDOS</span><strong>04</strong><em>No periodo selecionado</em></div><div class="management-kpi"><span>MEDIA POR OPERACAO</span><strong>6,3 <small>t</small></strong><em>29 operacoes finalizadas</em></div></div><div class="management-grid"><section class="panel"><div class="panel-head"><span class="panel-title">TONELADAS POR CLIENTE</span><span class="panel-meta">Participacao no volume total</span></div><div class="client-volume">${managementMetrics.map(metric=>`<div class="client-row"><div class="client-row-head"><strong>${metric.client}</strong><span>${metric.tons} t <b>${metric.share}%</b></span></div><div class="volume-track"><i style="width:${metric.share*2.7}%"></i></div><small>${metric.bales.toLocaleString('pt-BR')} fardos</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><span class="panel-title">RESUMO DE VOLUME</span><span class="panel-meta">Por tipo de movimentacao</span></div><div class="volume-summary"><div><span>CARREGAMENTO</span><strong>102 t</strong><small>1.360 fardos</small></div><div><span>DESCARGA</span><strong>82 t</strong><small>1.100 fardos</small></div><div class="volume-total"><span>TOTAL</span><strong>184 t</strong><small>2.460 fardos</small></div></div></section></div><section class="panel management-table"><div class="panel-head"><span class="panel-title">DETALHAMENTO POR CLIENTE</span><button class="btn" onclick="toast('Relatorio de volume exportado')">EXPORTAR CSV</button></div><div class="table-wrap"><table class="operations"><thead><tr><th>CLIENTE</th><th>TONELADAS</th><th>FARDOS</th><th>% DO TOTAL</th><th>OPERACOES</th></tr></thead><tbody>${managementMetrics.map(metric=>`<tr><td><strong>${metric.client}</strong></td><td class="dt">${metric.tons} t</td><td>${metric.bales.toLocaleString('pt-BR')}</td><td>${metric.share}%</td><td>${metric.client==='Sul Quimica'?'11':metric.client==='Mercado Sul'?'8':metric.client==='Rede Aurora'?'6':'4'}</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderProgramming(){page.innerHTML=header('PROGRAMACAO','Veiculos programados para a operacao')+`<div class="program-tabs"><button class="program-tab active" data-program="CARREGAMENTO" onclick="switchProgramTab('CARREGAMENTO')">CARREGAMENTO</button><button class="program-tab" data-program="DESCARGA" onclick="switchProgramTab('DESCARGA')">DESCARGA</button></div><section class="panel paste-panel"><div class="panel-head"><span class="panel-title">▣ COLAR PROGRAMACAO (CTRL+V)</span><span class="panel-meta">Padrao especifico por operacao</span></div><div class="paste-body"><p id="program-instruction">Cole abaixo as linhas copiadas da planilha de carregamento. O layout oficial sera aplicado quando definido.</p><textarea id="program-paste" placeholder="Cole aqui as linhas copiadas do Excel (CTRL+V)"></textarea><div class="paste-actions"><span id="paste-status" class="muted">Nenhum dado recebido</span><button class="btn btn-primary" onclick="previewProgramming()">VISUALIZAR PREVIA</button></div></div></section><section class="panel preview-panel" id="program-preview"><div class="empty-state">Nenhuma programacao carregada para esta data.<br><span class="text-link">Cole os dados acima para visualizar a previa.</span></div></section>`;}
function switchProgramTab(type){document.querySelectorAll('.program-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.program===type)); const instruction=document.querySelector('#program-instruction'); if(instruction)instruction.textContent=`Cole abaixo as linhas copiadas da planilha de ${type.toLowerCase()}. O layout oficial sera aplicado quando definido.`; document.querySelector('#program-paste').value=''; document.querySelector('#paste-status').textContent='Nenhum dado recebido'; document.querySelector('#program-preview').innerHTML='<div class="empty-state">Nenhuma programacao carregada para esta data.<br><span class="text-link">Cole os dados acima para visualizar a previa.</span></div>';}
function previewProgramming(){const text=document.querySelector('#program-paste').value.trim(); const preview=document.querySelector('#program-preview'); if(!text){toast('Cole os dados da planilha antes de visualizar'); return;} const rows=text.split(/\r?\n/).filter(Boolean).map(row=>row.split('\t')); const columns=rows[0].map((_,index)=>`COLUNA ${index+1}`); preview.innerHTML=`<div class="panel-head"><span class="panel-title">PREVIA DA IMPORTACAO</span><span class="panel-meta">${rows.length} linha(s) · aguardando confirmacao</span></div><div class="table-wrap"><table class="operations"><thead><tr>${columns.map(column=>`<th>${column}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(row=>`<tr>${columns.map((_,index)=>`<td>${row[index]||'<span class="muted">vazio</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="preview-confirm"><span class="muted">O padrao definitivo sera validado antes de salvar.</span><button class="btn btn-primary" onclick="toast('Previa validada. Aguardando padrao oficial.')">CONFIRMAR IMPORTACAO</button></div>`; document.querySelector('#paste-status').textContent=`${rows.length} linha(s) pronta(s) para revisao`;}
function renderGeneric(view){const title=views[view].toUpperCase(); let content=view==='docas'?dockPanel():table(); if(view==='programacao') content=`<section class="panel"><div class="panel-head"><span class="panel-title">AGENDA OPERACIONAL</span><button class="btn btn-primary" onclick="toast('Importacao pronta para receber dados')">＋ IMPORTAR PROGRAMACAO</button></div>${table().replace(/<section class="panel table-panel">[\s\S]*?<\/section>/,'')}</section>`; if(view==='operacao-mobile') content=`<section class="panel" style="max-width:480px;margin:auto"><div class="panel-head"><span class="panel-title">MINHAS OPERACOES</span><span class="status blue"><i></i> AO VIVO</span></div>${operations.slice(0,3).map(o=>`<div style="padding:20px;border-bottom:1px solid var(--line)"><div class="dt">${o.dt}</div><h2 style="font:600 25px var(--display);margin:8px 0">${o.type}</h2><div class="muted">${o.plate} · ${o.client} · ${o.dock}</div><button class="btn btn-primary" style="width:100%;margin-top:18px" onclick="toast('Proxima acao registrada')">PROXIMA ACAO →</button></div>`).join('')}</section>`; page.innerHTML=header(title,`Acompanhamento e gestao de ${views[view].toLowerCase()}`)+filters()+content;}
const baseManagerialView=renderManagerial;renderManagerial=()=>{if(operations.length){baseManagerialView();return;}page.className='page managerial-page';page.innerHTML=header('DASHBOARD GERENCIAL','Analise de volume e produtividade da operacao')+`<div class="report-banner"><div><span>ANALISE GERENCIAL</span><strong>SEM DADOS NO PERIODO</strong><small>Cadastre ou importe operacoes para iniciar os indicadores.</small></div><div class="report-status">● AGUARDANDO DADOS</div></div><div class="history-kpis"><div><span>TONELADAS TOTAIS</span><strong>0 t</strong></div><div><span>FARDOS TOTAIS</span><strong>0</strong></div><div><span>CLIENTES</span><strong>0</strong></div><div><span>OPERACOES</span><strong>0</strong></div></div><section class="panel empty-report"><div class="empty-state">Nenhum dado gerencial encontrado.<br><span class="muted">Os totais por cliente aparecerao quando houver operacoes registradas.</span></div></section>`;};
function render(){const view=location.hash.slice(1)||'dashboard'; document.querySelectorAll('.nav-item').forEach(a=>a.classList.toggle('active',a.dataset.view===view)); document.querySelector('#breadcrumb').textContent=views[view]||'Dashboard'; view==='dashboard'?renderDashboard():view==='tempo-real'?renderRealtime():view==='programacao'?renderProgramming():view==='descarga'?renderOperationBoard('DESCARGA'):view==='carregamento'?renderOperationBoard('CARREGAMENTO'):view==='gerencial'?renderManagerial():view==='historico'?renderHistory():view==='usuarios'?renderUsers():view==='configuracoes'?renderSettings():renderGeneric(view);}
document.querySelectorAll('.nav-item').forEach(a=>a.addEventListener('click',()=>{if(window.innerWidth<1000)document.querySelector('#sidebar').classList.remove('open')})); document.querySelector('#menu-toggle').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open')); window.addEventListener('hashchange',render); window.addEventListener('keydown',event=>{if(event.key==='Escape'){closeOperationDetail();closeNotifications();closeDockEditor();}}); window.addEventListener('click',event=>{const panel=document.querySelector('#notifications-popover');if(panel?.classList.contains('open')&&!panel.contains(event.target)&&!event.target.closest('.notification'))closeNotifications();}); window.addEventListener('storage',event=>{if(event.key==='torre-sul-operations'&&event.newValue){operations.splice(0,operations.length,...JSON.parse(event.newValue));render();updateNotificationBadge();toast('Dados atualizados em outra aba');}}); window.toast=toast; window.actionOperation=actionOperation; window.editDock=editDock; window.saveDockEdit=saveDockEdit; window.showNotifications=showNotifications; window.closeNotifications=closeNotifications; window.refreshDashboard=refreshDashboard; window.openOperationDetail=openOperationDetail; window.closeOperationDetail=closeOperationDetail; window.closeDockEditor=closeDockEditor; window.persistState=persistState; persistState(); render(); updateNotificationBadge(); setInterval(updateClock,1000); setInterval(updateNotificationBadge,30000); setInterval(()=>{if(document.visibilityState==='visible')render();},30000);